public final class CountingStore implements Store {
    private final Store inner;                  // delegate, injected
    private int count;
    public CountingStore(Store inner) { this.inner = inner; }
    @Override public void save(String id) { count++; inner.save(id); }   // forwarded
    @Override public String load(String id) { return inner.load(id); }  // forwarded
}

